alter table public.business_project_material_returns add foreign key(tenant_id,material_issue_id) references public.business_project_materials(tenant_id,id);

alter table public.business_purchase_orders add column project_id uuid,add column procurement_award_id uuid,add foreign key(tenant_id,project_id) references public.business_projects(tenant_id,id),add foreign key(tenant_id,procurement_award_id) references public.business_procurement_awards(tenant_id,id);
alter table public.business_projects add column operational_state text not null default 'active' check(operational_state in ('active','paused','closed'));
alter table public.business_purchase_lines add column award_line_id uuid,add foreign key(tenant_id,award_line_id) references public.business_procurement_award_lines(tenant_id,id);
alter table public.business_project_materials add column purchase_line_id uuid,add foreign key(tenant_id,purchase_line_id) references public.business_purchase_lines(tenant_id,id);
create unique index business_budget_revision on public.business_budget_versions(tenant_id,project_id,revision) where status<>'cancelled';
create unique index business_count_item on public.business_stock_count_lines(tenant_id,count_id,item_id,coalesce(lot_id,'00000000-0000-0000-0000-000000000000'::uuid));
create index business_pr_line_parent on public.business_procurement_request_lines(tenant_id,request_id);
create index business_quote_line_parent on public.business_supplier_quote_lines(tenant_id,quote_id);
create index business_award_line_parent on public.business_procurement_award_lines(tenant_id,award_id);
create index business_budget_line_parent on public.business_budget_lines(tenant_id,budget_id);
create index business_count_line_parent on public.business_stock_count_lines(tenant_id,count_id);

update public.business_entity_definitions set definition='{"label":"Đơn mua hàng","feature":"purchasing","mode":"order","fields":{"partner_id":{"label":"Nhà cung cấp","type":"ref","ref":"partners","required":true},"order_date":{"label":"Ngày đặt mua","type":"date","required":true},"expected_on":{"label":"Ngày dự kiến nhận","type":"date","required":true},"project_id":{"label":"Công trình","type":"ref","ref":"projects","required":false,"requiresFeature":"projects"},"procurement_award_id":{"label":"Nguồn lựa chọn NCC","type":"ref","ref":"procurement_awards","required":false,"computed":true}}}'::jsonb where kind='purchase_orders';

update public.business_entity_definitions set definition='{"label":"Chi tiết đơn mua","feature":"purchasing","mode":"master","fields":{"purchase_order_id":{"label":"Đơn mua","type":"ref","ref":"purchase_orders","required":true},"item_id":{"label":"Vật tư / hàng hóa","type":"ref","ref":"items","required":true},"quantity":{"label":"Số lượng","type":"number","default":0,"min":0.0001},"unit_price":{"label":"Đơn giá","type":"number","default":0,"min":0},"award_line_id":{"label":"Dòng lựa chọn NCC","type":"ref","ref":"procurement_award_lines","required":false,"computed":true}}}'::jsonb where kind='purchase_lines';

update public.business_entity_definitions set definition='{"label":"Vật tư công trình","feature":"projects","mode":"document","fields":{"project_id":{"label":"Công trình","type":"ref","ref":"projects","required":true},"item_id":{"label":"Vật tư","type":"ref","ref":"items","required":true},"warehouse_id":{"label":"Kho","type":"ref","ref":"warehouses","required":true},"lot_id":{"label":"Lô","type":"ref","ref":"lots"},"quantity":{"label":"Số lượng","type":"number","min":0.0001,"required":true},"unit_cost":{"label":"Đơn giá được duyệt","type":"number","min":0,"default":0},"document_date":{"label":"Ngày chứng từ","type":"date","required":true},"purchase_line_id":{"label":"Dòng đặt mua cho công trình","type":"ref","ref":"purchase_lines","required":false,"requiresFeature":"purchasing"}}}'::jsonb where kind='project_materials';

update public.business_entity_definitions set definition='{"label":"Công trình & ngân sách","feature":"projects","mode":"master","fields":{"budget":{"label":"Ngân sách","type":"number","min":0,"default":0},"starts_on":{"label":"Ngày bắt đầu","type":"date","required":true},"ends_on":{"label":"Ngày kết thúc dự kiến","type":"date"},"operational_state":{"label":"Trạng thái công trình","type":"enum","values":{"active":"Đang thi công","paused":"Tạm dừng","closed":"Đã khóa"},"required":true,"default":"active","computed":true}}}'::jsonb where kind='projects';
